bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env;
const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
const base=e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org';
if(!['https://api.telegram.org','http://telegram-bot-api:8081'].includes(base))throw Error('BOT_API_NOT_ADMITTED');
const url=base+'/bot'+token+'/editMessageReplyMarkup';
const body={chat_id:-1002373696859,message_id:4689,
 reply_markup:{inline_keyboard:[[{text:'⭐ Stars本編・購入はこちら',url:'https://t.me/c/2373696859/4691'}]]}};
const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(25000)});
let result={};
try{result=await r.json()}catch{}
console.log('TELEGRAM_HTTP_STATUS='+r.status);
console.log('TELEGRAM_ERROR_CODE='+String(result.error_code??'NONE'));
const reason=String(result.description??'').toLowerCase();
const cases=['message is not modified','message to edit not found','message can\'t be edited','message identifier is not specified','not enough rights','chat not found','button_url_invalid','button url invalid','message to edit not found'];
const match=cases.find(x=>reason.includes(x));
console.log('TELEGRAM_ERROR_CLASS='+ (match?match.replaceAll(' ','_').toUpperCase():result.ok===true?'SUCCESS':'OTHER'));
console.log('EDIT_RESPONSE_OK='+String(result.ok===true));
if(result.ok===true){
 if(result.result!==true && result.result?.message_id!==4689)throw Error('EDIT_ACK_MISMATCH');
 console.log('LINKED_PREVIEW=PASS');
}else if(r.status>=500){throw Error('TELEGRAM_SERVER_ERROR');}
NODE
